use gpui_dataset_transformation::{FieldStats, calculator, field_statistics, histogram, probe, resample_to_grid};
use gpui_mesh::{Association, DataSet, Field};
use gpui_profiler::AllocProbe;
use std::hint::black_box;
use std::time::Instant;

enum Output { Data(DataSet), Stats(FieldStats), Histogram(Vec<(f64,usize)>), Probe(Vec<Option<f64>>) }

fn measure(n:usize,case:&str,mut run:impl FnMut()->Output,check:impl Fn(&Output)) {
    let warm=black_box(run());check(&warm);drop(warm);
    let mut times=Vec::with_capacity(5);let mut calls=Vec::with_capacity(5);let mut bytes=Vec::with_capacity(5);
    for _ in 0..5 {
        let mut allocations=AllocProbe::new();let start=Instant::now();let output=black_box(run());let elapsed=start.elapsed().as_nanos();let sample=allocations.sample("analysis");
        times.push(elapsed);calls.push(sample.count);bytes.push(sample.bytes);check(&output);drop(output);
    }
    println!(r#"{{"n":{n},"case":"{case}","times_ns":{times:?},"allocation_calls":{calls:?},"allocated_bytes":{bytes:?},"allocator_instrumentation":{}}}"#,cfg!(feature="allocations"));
}

fn grid(n:usize)->DataSet {
    let mut data=DataSet::structured_grid("probe",[n;3],[0.0;3],[1.0/(n-1) as f64;3]).unwrap();
    data.point_data.push(Field::scalar("p",data.positions.iter().map(|p|p[0]+2.0*p[1]+3.0*p[2]).collect::<Vec<_>>()));
    data.point_data.push(Field::scalar("q",data.positions.iter().map(|p|0.5*p[0]+p[2]).collect::<Vec<_>>()));data
}

fn main() {
    for n in [16usize,32,48] {
        let mut data=grid(n);
        let count=data.point_count();
        let values=(0..count).map(|i|((i*15_485_863)%65_536) as f64/65_536.0).collect::<Vec<_>>();
        let expected_mean=values.iter().sum::<f64>()/count as f64;
        data.point_data[0]=Field::scalar("p",values);
        measure(n,"calculator",||Output::Data(calculator(&data,"min(sqrt(p+1),abs(q))+sin(x)+cos(y)+max(p,q)","result").unwrap()),|output| {
            let Output::Data(output)=output else {panic!()};output.validate().unwrap();
            let values=output.field(Association::Point,"result").unwrap().as_scalar().unwrap();
            for (i,position) in data.positions.iter().enumerate() {
                let p=data.point_data[0].as_scalar().unwrap()[i];let q=data.point_data[1].as_scalar().unwrap()[i];
                let expected=(p+1.0).sqrt().min(q.abs())+position[0].sin()+position[1].cos()+p.max(q);
                assert!((values[i]-expected).abs()<1e-12);
            }
        });
        measure(n,"statistics",||Output::Stats(field_statistics(&data,"p",Association::Point).unwrap()),|output| {
            let Output::Stats(stats)=output else {panic!()};assert_eq!(stats.count,count);assert!((stats.mean-expected_mean).abs()<1e-12);assert!(stats.std_dev>0.0&&stats.std_dev<1.0);
        });
        measure(n,"histogram",||Output::Histogram(histogram(&data,"p",64).unwrap()),|output| {
            let Output::Histogram(bins)=output else {panic!()};assert_eq!(bins.len(),64);assert_eq!(bins.iter().map(|(_,count)|count).sum::<usize>(),count);assert!(bins.iter().all(|(center,_)|center.is_finite()));
        });
    }
    for n in [8usize,16,24] {
        let data=grid(n);
        let queries=(0..64).map(|i|[(i as f64+0.5)/64.0,((i*17)%64) as f64/64.0,((i*37)%64) as f64/64.0]).collect::<Vec<_>>();
        measure(n,"probe",||Output::Probe(probe(&data,"p",&queries).unwrap()),|output| {
            let Output::Probe(values)=output else {panic!()};for (value,p) in values.iter().zip(&queries) {assert!((value.unwrap()-(p[0]+2.0*p[1]+3.0*p[2])).abs()<1e-9);}
        });
        for (case,index) in [("probe_single_near",0),("probe_single_far",63)] {
            let query=&queries[index..index+1];
            measure(n,case,||Output::Probe(probe(&data,"p",query).unwrap()),|output| {
                let Output::Probe(values)=output else {panic!()};let p=query[0];assert!((values[0].unwrap()-(p[0]+2.0*p[1]+3.0*p[2])).abs()<1e-9);
            });
        }
        for count in [8usize,32] {
            let query=&queries[..count];let case=format!("probe_{count}");
            measure(n,&case,||Output::Probe(probe(&data,"p",query).unwrap()),|output| {
                let Output::Probe(values)=output else {panic!()};for (value,p) in values.iter().zip(query) {assert!((value.unwrap()-(p[0]+2.0*p[1]+3.0*p[2])).abs()<1e-9);}
            });
        }
        for count in [128usize,256] {
            let query=(0..count).map(|i|[(i as f64+0.5)/count as f64,((i*17)%count) as f64/count as f64,((i*37)%count) as f64/count as f64]).collect::<Vec<_>>();let case=format!("probe_{count}");
            measure(n,&case,||Output::Probe(probe(&data,"p",&query).unwrap()),|output| {
                let Output::Probe(values)=output else {panic!()};for (value,p) in values.iter().zip(&query) {assert!((value.unwrap()-(p[0]+2.0*p[1]+3.0*p[2])).abs()<1e-9);}
            });
        }
    }
    for n in [4usize,6,8] {
        let data=grid(n);
        measure(n,"resample",||Output::Data(resample_to_grid(&data,[n+1;3],[0.0;3],[1.0/n as f64;3],-7.0).unwrap()),|output| {
            let Output::Data(output)=output else {panic!()};output.validate().unwrap();
            for field in &output.point_data {let values=field.as_scalar().unwrap();for (i,p) in output.positions.iter().enumerate() {let expected=if field.name.as_ref()=="p" {p[0]+2.0*p[1]+3.0*p[2]} else {0.5*p[0]+p[2]};assert!((values[i]-expected).abs()<1e-9);}}
        });
    }
}

